/**
 * Validation rule interface
 */
export interface ValidationRule {
    /**
     * Whether field is required
     */
    required?: boolean;
    /**
     * Expected data type
     */
    type?: string;
    /**
     * Minimum value for numbers
     */
    minimum?: number;
    /**
     * Maximum value for numbers
     */
    maximum?: number;
    /**
     * Regular expression pattern for strings
     */
    pattern?: string | RegExp;
    /**
     * Allowed values (enum)
     */
    enum?: unknown[];
    /**
     * Minimum string length
     */
    minLength?: number;
    /**
     * Maximum string length
     */
    maxLength?: number;
    /**
     * Default value
     */
    default?: unknown;
    /**
     * Custom validator function
     */
    validator?(value: unknown): boolean | string;
}
/**
 * Validation schema type
 */
export type ValidationSchema = Record<string, ValidationRule>;
/**
 * Validates configuration object against schema
 *
 * @param config - Configuration to validate
 * @param schema - Validation schema
 * @throws Error if validation fails
 */
export declare const validateConfig: (config: object, schema: ValidationSchema) => void;
/**
 * Validates a single value against a rule
 *
 * @param value - Value to validate
 * @param rule - Validation rule
 * @returns Validation result (true if valid, error message if invalid)
 */
export declare const validateValue: (value: unknown, rule: ValidationRule) => true | string;
/**
 * Applies default values from schema to config
 *
 * @param config - Configuration object
 * @param schema - Validation schema with defaults
 * @returns Configuration with defaults applied
 */
export declare const applyDefaults: <T extends object>(config: T, schema: ValidationSchema) => T;
